<?php $pageTitle='Overview';require __DIR__.'/_top.php';$pdo=db();$counts=[];foreach(['users'=>'Members','flowers'=>'Flower listings','auctions'=>'Auctions','orders'=>'Orders','enquiries'=>'Enquiries'] as $t=>$label){$counts[$label]=(int)$pdo->query("SELECT COUNT(*) FROM `$t`")->fetchColumn();}$revenue=(float)$pdo->query("SELECT COALESCE(SUM(amount),0) FROM payments WHERE status='paid'")->fetchColumn();$recent=$pdo->query("SELECT name,email,role,status,created_at FROM users ORDER BY created_at DESC LIMIT 6")->fetchAll(); ?>
<section class="welcome-panel"><div><span class="eyebrow">YOUR FLOWER EXCHANGE AT A GLANCE</span><h2>Good day, <?= e($_SESSION['admin_name']) ?>.</h2><p>Here is what's happening across your marketplace today.</p></div><a class="btn btn-light" href="<?= url('admin/flowers.php') ?>">＋ Add flower listing</a></section>
<div class="metric-grid"><?php foreach($counts as $label=>$value): ?><article class="metric-card"><span><?= e($label) ?></span><strong><?= number_format($value) ?></strong><small>All-time records</small></article><?php endforeach; ?><article class="metric-card metric-highlight"><span>Paid revenue</span><strong>₹<?= number_format($revenue,2) ?></strong><small>Successful payments</small></article></div>
<div class="admin-columns"><section class="panel"><div class="panel-heading"><div><span class="eyebrow">MEMBER ACTIVITY</span><h2>Recent registrations</h2></div><a href="<?= url('admin/users.php') ?>">View all ↗</a></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Role</th><th>Status</th><th>Joined</th></tr></thead><tbody><?php foreach($recent as $u): ?><tr><td><b><?= e($u['name']) ?></b><small class="subline"><?= e($u['email']) ?></small></td><td><?= e(ucfirst($u['role'])) ?></td><td><span class="status"><?= e($u['status']) ?></span></td><td><?= e(date('d M',strtotime($u['created_at']))) ?></td></tr><?php endforeach; ?><?php if(!$recent): ?><tr><td colspan="4">No registrations yet.</td></tr><?php endif; ?></tbody></table></div></section><section class="panel"><span class="eyebrow">QUICK ACTIONS</span><h2>Manage your platform</h2><div class="quick-links"><a href="<?= url('admin/flowers.php') ?>">✿ Manage flower listings <span>→</span></a><a href="<?= url('admin/auctions.php') ?>">◇ Schedule an auction <span>→</span></a><a href="<?= url('admin/users.php') ?>">♙ Review members <span>→</span></a><a href="<?= url('admin/analytics.php') ?>">▥ View analytics <span>→</span></a></div></section></div>
